-- Lliçons fixes de Fonètica, elocució i ortografia del C2 (botó «Aprendre lliçó»).
-- Com les del C1, cada lliçó és una adaptació didàctica de nivell C2 redactada a partir de:
--   - l'abast de cada contingut del C2 (Quadern C2 de la JQCV, 3.2.1), descrit en
--     20261026100000_practice_fonetica_c2.sql;
--   - les regles de la Gramàtica valenciana bàsica (GVB) i de la Gramàtica normativa
--     valenciana (GNV) de l'AVL, descarregades una sola vegada en assets-src/avl/.
-- El contingut es guarda en metadata.lesson, amb els enllaços als apartats de la GVB i la GNV en
-- metadata.lesson.sources. La migració de continguts (20261026100000) conserva metadata.lesson si es
-- torna a aplicar. Tornar a aplicar este fitxer no canvia res més.

UPDATE public.resources r SET
  metadata = coalesce(r.metadata, '{}'::jsonb) || jsonb_build_object('lesson', l.lesson)
FROM jsonb_to_recordset($data$[
  {"type": "c2_fon_elocucio", "lesson": {"intro": "Aprendràs a aplicar els criteris d'elocució estàndard en els casos més formals i difícils: els enllaços entre paraules, els sons sonors que no es veuen en l'escriptura, la fonètica sintàctica, l'accent de paraules cultes i els matisos que aporta l'entonació.", "blocks": [{"title": "Enllaços: sinalefes i elisions", "text": "En l'elocució estàndard les paraules no es pronuncien aïllades. La vocal final d'una paraula i la inicial de la següent poden formar una sola síl·laba (**sinalefa**): *no ho sé* [nów sé], *espera un moment* [espéɾawn momént]. Hi ha **elisió** quan les dos vocals són idèntiques, sobretot si són àtones (*una aigua*, *entre els carrers*); quan la segona paraula comença per *e* àtona + consonant (*una escala* [unaskála]), i quan una *-a* o una *-e* àtones finals precedixen una vocal, especialment si és tònica (*mitja hora*, *onze anys*). Són enllaços **propis de l'estàndard**, també en registre formal.", "table": {"head": ["fenomen", "exemple", "pronúncia"], "rows": [["sinalefa", "*no hi ha res*", "[nó já rés]"], ["vocals idèntiques", "*no oblides*", "[nóblíðes]"], ["*e* àtona + consonant", "*no es coneixen*", "[nós konéjʃen]"], ["*-a*, *-e* + vocal tònica", "*quina hora*, *onze anys*", "[kinɔ́ɾa], [onzáɲs]"]]}}, {"title": "Sons sonors que l'escriptura no mostra", "text": "Alguns sons sonors no es dedueixen de la grafia. La *x* dels grups inicials *ex-* i *inex-* seguits de vocal, *h* o consonant sonora sona **[gz]**: *examen* [egzámen], *exhortar*, *exdiputat*, *inexorable* [inegzoɾáble]. Els derivats i compostos de *fons*, *dins* i *trans* s'escriuen amb *s* davant de vocal, però la *s* sona **sonora** [z]: *enfonsar*, *endinsar*, *transatlàntic*; igualment *transistor* [tɾanzistóɾ]. El grup *tz* del sufix *-itzar* també sona [z]: *analitzar* [analizáɾ]. En canvi, cal mantindre **sordes** les *ss* i les *c*: *comissió*, *impressió*, *funció*.", "watch": [{"wrong": "*e[ks]amen*, *e[ks]acte*", "right": "e[gz]amen, e[gz]acte"}, {"wrong": "*e[ʤ]ecutar*, *e[ʤ]ercici*", "right": "e[gz]ecutar, e[gz]ercici"}, {"wrong": "*tran[s]istor*, *[s]ero*, *on[s]e*", "right": "tran[z]istor, [z]ero, on[z]e"}, {"wrong": "*comi[z]ió*, *fun[z]ió*", "right": "comi[s]ió, fun[s]ió"}]}, {"title": "Fonètica sintàctica: ensordiments, sonoritzacions i emmudiments", "text": "Les oclusives finals es pronuncien **sordes** davant de pausa, de vocal o de consonant sorda (*verd obscur* [vɛ́ɾt], *club animat* [klúp]) i **sonores** davant de consonant sonora (*blat bord* [blád], *príncep blau* [pɾínseb]). Les fricatives i africades finals (*s*, *ç*, *-ix*, *-ig*, *-tx*) es fan **sonores** davant de vocal o de consonant sonora (*peix al forn* [péjʒ], *despatx obert* [despáʤ]). En els grups finals *-mp*, *-nt*, *-lt* és acceptable, on és propi, **emmudir** l'oclusiva (*camp* [kám], *molt* [mól]), però la *t* de *-nt* **es manté** davant de vocal: *sant Antoni*, *vint hòmens*.", "table": {"head": ["context", "exemple", "pronúncia"], "rows": [["oclusiva + vocal", "*sac estret*", "[sák estɾét]"], ["oclusiva + consonant sonora", "*fred matutí*", "[fɾéd matutí]"], ["*-ig* + vocal", "*roig encés*", "[rɔ́ʤ ensés]"], ["*-nt* + vocal", "*quant és*", "[kwánt és], no [kwànés]"], ["*-ts* davant de pausa", "*plats*", "[pláts], no [pláʧ]"]]}}, {"title": "Assimilacions i geminacions en el registre formal", "text": "Les nasals s'**assimilen** a la consonant següent: *un pa* [um pá], *enfadar* [eɱfaðáɾ]; *amb* sona [amb] davant de vocal i [am] o [an] davant de consonant. En els grups gràfics cal distingir paraules **patrimonials** i **cultes**: en *tl* i *tn* patrimonials és preferible la geminada (*ametla* [amélla], *cotna* [kónna]); *tm* patrimonial és simple (*setmana* [semána]); en els cultismes, [dl], [dm], [dn] (o geminada). *Submarí* es pronuncia preferiblement [submaɾí]; en *suggerir* i *innocent* la primera consonant és muda. La *l·l* geminada [ll] és pròpia només de registres **molt formals**.", "table": {"head": ["grafia", "patrimonial", "culte"], "rows": [["*tl*", "*ametla*, *vetla*: [ll] (o [l])", "*atleta*, *atles*: [dl] (o [ll])"], ["*tm*", "*setmana*, *sotmetre*: [m]", "*arrítmia*, *algoritme*: [dm] (o [mm])"], ["*tn*", "*cotna*: [nn] (o [n])", "*ètnia*, *vietnamita*: [dn] (o [nn])"]]}}, {"title": "Accent dubtós en l'elocució formal", "text": "Moltes paraules cultes tenen la síl·laba tònica en un lloc diferent del castellà, i en l'elocució formal cal pronunciar-les bé. Recorda també que les formes accentuades en el radical dels verbs en *-iar* porten l'accent en la *i* (*ell estudia* [estuðía], *canvien*), les dels verbs en *-quar*, en la vocal anterior a la *q* (*adequa*, *liqües*), i les dels verbs en *-cuar*, en la *u* (*evacua* [evakúa]). *Aurèola* és esdrúixola; *rèptil* i *tèxtil*, planes.", "table": {"head": ["paraula", "síl·laba tònica"], "rows": [["*acne*, *atmosfera*", "**ac**-ne, at-mos-**fe**-ra"], ["*ciclop*, *miop*", "ci-**clop**, mi-**op**"], ["*etíop*, *monòlit*, *medul·la*", "e-**tí**-op, mo-**nò**-lit, me-**dul**-la"], ["*diòptria*, *període*", "di-**òp**-tri-a, pe-**rí**-o-de"], ["*timpà*", "tim-**pà**"]]}, "watch": [{"wrong": "*ell estúdia*, *canvíen*", "right": "ell estudia, canvien"}, {"wrong": "*atmòsfera*, *cíclop*, *mèdul·la*", "right": "atmosfera, ciclop, medul·la"}]}, {"title": "Entonació i matisos de significat", "text": "La **corba melòdica** pot canviar el sentit d'un enunciat amb les mateixes paraules: *Ha preparat el sopar Pere* és declarativa o interrogativa segons l'entonació. El **focus** informatiu es pronuncia amb més intensitat i sol anar al final; quan s'anteposa un element per a destacar-lo (**rematització**), l'èmfasi és tonal i no hi ha pronom que el reprenga (*De Pere parlaven, no de Juli*). Els elements **dislocats** i els incisos tenen una inflexió pròpia, que l'escriptura marca amb comes o guions. El to i les pauses també permeten expressar ironia, retret o vacil·lació.", "examples": ["*Has llegit l'informe?* (interrogativa total: to final ascendent)", "***Amb el meu germà*** *van parlar, no amb el teu.* (rematització: èmfasi tonal, sense pronom)", "*El café, el pren sempre sense sucre.* (dislocació a l'esquerra, amb inflexió i pronom)", "*Molt bé, sí, molt bé...* (to irònic: el sentit és el contrari)"]}], "remember": ["Sinalefes i elisions (*no ho sé*, *mitja hora*, *una escala*) són pròpies de l'estàndard.", "*Examen*, *exhortar*, *inexorable*: [gz]; *transistor*, *transatlàntic*, *enfonsar*: [z].", "Oclusives finals sordes, i sonores només davant de consonant sonora (*blat bord* [blád]).", "La *t* de *-nt* es pronuncia davant de vocal: *sant Antoni*, *vint hòmens*.", "*Acne*, *atmosfera*, *ciclop*, *miop*, *etíop*, *medul·la*, *monòlit*, *diòptria*, *període*, *timpà*; *ell estudia*.", "L'entonació distingix la modalitat, marca el focus i els incisos i aporta matisos com la ironia."], "sources": [{"gram": "GNV", "section": "1.4.1", "title": "Vocals en contacte", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_4_1"}, {"gram": "GVB", "section": "3.1", "title": "Vocals en contacte", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=3_1"}, {"gram": "GNV", "section": "1.4.2.1", "title": "Les consonants oclusives en posició final", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_4_2_1"}, {"gram": "GNV", "section": "1.4.2.2", "title": "Les consonants fricatives i africades en posició final", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_4_2_2"}, {"gram": "GVB", "section": "3.2.2", "title": "El grup ‑nt", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=3_2_2"}, {"gram": "GNV", "section": "1.3.2.1", "title": "Les consonants oclusives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_1"}, {"gram": "GNV", "section": "1.3.2.3", "title": "Les consonants sibilants alveolars", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_3"}, {"gram": "GNV", "section": "1.3.2.5", "title": "Les consonants laterals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_5"}, {"gram": "GNV", "section": "1.3.2.7", "title": "Les consonants nasals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_7"}, {"gram": "GNV", "section": "4.8", "title": "La representació del grup fònic [ks]", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_8"}, {"gram": "GNV", "section": "1.5", "title": "L'accentuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_5"}, {"gram": "GVB", "section": "3.3", "title": "L'accentuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=3_3"}, {"gram": "GNV", "section": "8.6", "title": "La modalitat oracional", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=8_6"}, {"gram": "GNV", "section": "8.7", "title": "L'estructura informativa", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=8_7"}]}},
  {"type": "c2_fon_vocals", "lesson": {"intro": "Aprendràs a escriure les vocals dels pseudoderivats i dels compostos cultes, les paraules invariables en *-us*, la *e* de suport dels préstecs i dels derivats, les vocals que contrasten amb altres llengües i el timbre de les *e* i les *o* que generen dubtes.", "blocks": [{"title": "Pseudoderivats: i/e i o/u", "text": "Molts cultismes no deriven de la paraula patrimonial, sinó directament del llatí, i en conserven la vocal: són **pseudoderivats**. Per això no es pot traslladar la vocal d'una paraula a l'altra: *línia*, però *alinear* i *lineal*; *doble*, però *duplicar*; *full*, però *foliació*.", "table": {"head": ["paraula patrimonial", "pseudoderivat culte"], "rows": [["*línia*", "*alinear*, *alineació*, *lineal*"], ["*doble*", "*duplicar*, *duplicitat*"], ["*full*, *fulla*", "*foliació*, *foliar*"], ["*pèl*", "*pilós*"], ["*fe*", "*fidel*"], ["*peix*", "*piscicultura*"]]}, "watch": [{"wrong": "*aliniar*, *aliniació*", "right": "alinear, alineació"}, {"wrong": "*doplicar*", "right": "duplicar"}, {"wrong": "*fuliació*", "right": "foliació"}]}, {"title": "Compostos cults: a i e", "text": "Els compostos i derivats formats amb arrels gregues i llatines mantenen la vocal del **formant culte**, encara que la pronunciació col·loquial la desfigure. La *a-* (o *an-*) privativa, que vol dir ‘sense’, apareix en *astigmatisme*, *asimetria* o *anestèsia*; en els altres formants cal recordar la vocal pròpia de cada un.", "table": {"head": ["formant", "valor", "exemples"], "rows": [["*a-*, *an-*", "‘sense’", "*astigmatisme*, *asimetria*, *anestèsia*"], ["*aero-*", "‘aire’", "*aeròdrom*, *aeronau*, *aeroport*"], ["*hemo-*, *hemato-*", "‘sang’", "*hemoglobina*, *hematoma*"], ["*-algia*", "‘dolor’", "*neuràlgia*, *nostàlgia*"], ["*paleo-*", "‘antic’", "*paleolític*, *paleontologia*"]]}, "watch": [{"wrong": "*areoport*, *areòdrom*", "right": "aeroport, aeròdrom"}]}, {"title": "Paraules invariables en -us", "text": "Alguns llatinismes i cultismes acaben en ***-us***, amb *u* i no amb *-os*, i són **invariables**: el nombre el marca el determinant (*el campus / els campus*). Es pronuncien amb [u] final: *l'àngelus*, *el cactus*, *el campus*, *el corpus*, *l'ictus*, *el lapsus*, *el plus*, *el porus*, *el rictus*, *el sinus*, *el tifus*, *el vulgus*. Si són esdrúixoles, duen accent (*àngelus*).", "examples": ["Els **campus** de les tres universitats tenen biblioteques obertes de vesprada.", "Va patir un **ictus** i, després, uns quants **lapsus** de memòria."], "watch": [{"wrong": "*els campos*, *uns lapsos*", "right": "els campus, uns lapsus"}, {"wrong": "*el cacto*, *el tifos*", "right": "el cactus, el tifus"}]}, {"title": "Préstecs: e de suport, accent i k, w, y", "text": "Els préstecs que en la llengua d'origen comencen per *s* + consonant prenen una ***e-* de suport** quan s'adapten: *espot*, *esquaix*, *estàndard*, *escàner*, *eslàlom*, *estrés*. Els préstecs **adaptats** s'escriuen en redona i s'accentuen segons les regles generals (*escàner*, *míting*); els **no adaptats** van en cursiva i amb la grafia d'origen, sense afegir-hi accents (*apartheid*, *per capita*). Les lletres *k*, *w* i *y* es mantenen en alguns préstecs i s'adapten en altres.", "table": {"head": ["es mantenen", "s'adapten"], "rows": [["*vodka*, *karate*, *judoka*", "*estoc* (‘stock’), *quiosc*"], ["*kiwi*, *hawaià*", "*vàter* (‘water’)"], ["*whisky* (no adaptat, en cursiva)", "*hoquei* (‘hockey’)"]]}}, {"title": "Vocals que contrasten amb altres llengües i e de suport", "text": "Algunes paraules tenen una vocal diferent de la del castellà: *arravatar-se* (‘arrebatarse’), *ciment* (‘cemento’), *bambolina* (‘bambalina’), *sarbatana* (‘cerbatana’), *escrúpol* (‘escrúpulo’), *cònsol* (‘cónsul’). D'altra banda, quan un prefix acabat en vocal s'unix a una paraula que comença per ***e***, es mantenen les dos vocals: *infraestructura*, *reescriure*, *reestructurar*, *contraespionatge*.", "watch": [{"wrong": "*arrebatar-se*, *cement*", "right": "arravatar-se, ciment"}, {"wrong": "*bambalina*, *cerbatana*", "right": "bambolina, sarbatana"}, {"wrong": "*infrastructura*, *rescriure*", "right": "infraestructura, reescriure"}]}, {"title": "E i o obertes o tancades: casos dubtosos", "text": "En algunes paraules el timbre de la *e* o la *o* tònica no es pot deduir de les tendències generals i cal memoritzar-lo. Com que no duen accent gràfic, l'escriptura no ajuda: la pronunciació formal ha de seguir la que recullen el Quadern C2 i el DNV. En unes poques paraules s'admeten els dos timbres.", "table": {"head": ["paraula", "pronúncia estàndard"], "rows": [["*contesta*", "cont[e]sta (tancada)"], ["*postres*, *sostre*", "p[o]stres, s[o]stre (tancada)"], ["*toll*, *xanglot*", "t[o]ll, xangl[o]t (tancada)"], ["*flota*", "fl[ɔ]ta (oberta)"], ["*les Corts*, *mot*", "C[ɔ]rts o C[o]rts; m[ɔ]t o m[o]t"]]}}], "remember": ["Pseudoderivats amb la vocal llatina: *línia/alinear*, *doble/duplicar*, *full/foliació*.", "Formants cultes: *astigmatisme*, *aeroport*, *hematoma*, *neuràlgia*.", "Invariables en *-us*: *el campus / els campus*, *l'ictus*, *el lapsus*, *el tifus*.", "*E-* de suport en préstecs (*espot*, *esquaix*) i doble *e* en *infraestructura*, *reescriure*.", "*Arravatar-se*, *ciment*, *bambolina*, *sarbatana*.", "*Cont[e]sta*, *p[o]stres*, *s[o]stre*, *t[o]ll*, *xangl[o]t*, però *fl[ɔ]ta*."], "sources": [{"gram": "GVB", "section": "6.2", "title": "Les grafies a i e", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_2"}, {"gram": "GVB", "section": "6.3", "title": "Les grafies o i u", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_3"}, {"gram": "GNV", "section": "1.2.1.3", "title": "La distribució de la e i la o obertes", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_2_1_3"}, {"gram": "GNV", "section": "1.2.2.3", "title": "Criteris particulars de pronunciació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_2_2_3"}, {"gram": "GVB", "section": "1.2.1", "title": "Les vocals tòniques", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=1_2_1"}, {"gram": "GVB", "section": "7.10", "title": "L'accentuació de paraules estrangeres", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=7_10"}, {"gram": "GVB", "section": "7.11", "title": "L'accentuació de paraules o expressions llatines", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=7_11"}, {"gram": "GVB", "section": "10.7", "title": "L'apostrofació davant de s líquida", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_7"}, {"gram": "GVB", "section": "6.6", "title": "La grafia k", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_6"}, {"gram": "GVB", "section": "6.27", "title": "La grafia w", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_27"}, {"gram": "GVB", "section": "6.26", "title": "La grafia y", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_26"}, {"gram": "GNV", "section": "4.18", "title": "La grafia w", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_18"}]}},
  {"type": "c2_fon_accentuacio", "lesson": {"intro": "Aprendràs a accentuar els casos de més dificultat: cultismes d'ús formal amb la síl·laba tònica en un lloc diferent del castellà, paraules d'ús general que generen dubtes, les terminacions en *-ia* i *-íac*, i els noms propis de persona i de lloc.", "blocks": [{"title": "Cultismes d'ús restringit", "text": "En alguns cultismes, sobretot científics i mèdics, la síl·laba tònica no coincidix amb la del castellà. Una vegada situat l'accent, s'apliquen les **regles generals**: *alvèol* és plana acabada en consonant (accent), *èczema* és esdrúixola (accent) i *cotilèdon* és plana acabada en *-on* (accent). Totes tres tenen *e* tònica oberta, per això porten accent greu.", "table": {"head": ["valencià", "tònica", "castellà"], "rows": [["*alvèol*", "al-**vè**-ol", "*alveolo*"], ["*èczema*", "**èc**-ze-ma", "*eccema*"], ["*cotilèdon*", "co-ti-**lè**-don", "*cotiledón*"], ["*pneumònia*", "pneu-**mò**-ni-a", "*neumonía*"], ["*elit*", "e-**lit**", "*élite*"]]}}, {"title": "Paraules d'ús general amb dubtes", "text": "Moltes paraules freqüents tenen una accentuació que contrasta amb la del castellà. Si es localitza bé la síl·laba tònica, l'accent gràfic es dedueix sense excepcions de les regles generals.", "table": {"head": ["paraula", "tipus", "accent gràfic"], "rows": [["*acne*, *atmosfera*, *medul·la*", "planes acabades en vocal", "no"], ["*ciclop*, *miop*", "agudes acabades en consonant", "no"], ["*etíop*, *monòlit*", "planes acabades en consonant", "sí"], ["*diòptria*, *període*", "esdrúixoles", "sí"], ["*timpà*", "aguda acabada en vocal", "sí"]]}, "watch": [{"wrong": "*acné*, *atmòsfera*, *mèdul·la*", "right": "acne, atmosfera, medul·la"}, {"wrong": "*cíclop*, *etiop*, *monolit*", "right": "ciclop, etíop, monòlit"}, {"wrong": "*dioptria*, *tímpan*", "right": "diòptria, timpà"}]}, {"title": "-ia tònica o àtona i paraules en -íac", "text": "La terminació *-ia* pot ser **àtona** (paraula esdrúixola, amb accent: *anèmia*, *leucèmia*, *diòptria*, *pneumònia*) o **tònica** (paraula plana, sense accent: *policia*, *energia*, *teoria*, *cirurgia*). Cal fixar-se en la forma valenciana, perquè no sempre coincidix amb el castellà. Els adjectius i noms en ***-íac*** porten l'accent en la *i*: *cardíac*, *policíac*, *elegíac*, *amoníac*, *zodíac*.", "table": {"head": ["-ia àtona (esdrúixola)", "-ia tònica (plana)"], "rows": [["*anèmia*, *leucèmia*", "*policia*, *energia*"], ["*diòptria*, *pneumònia*", "*teoria*, *cirurgia*"]]}, "watch": [{"wrong": "*anemia*, *pneumonia*", "right": "anèmia, pneumònia"}, {"wrong": "*cardiac*, *zodiac*", "right": "cardíac, zodíac"}]}, {"title": "Antropònims", "text": "Els noms de persona **adaptats** s'accentuen com qualsevol altra paraula: *Vladímir* (plana acabada en *-r*), *Sòcrates*, *Aristòtil* i *Èsquil*, però *Plató* i *Ciceró* (agudes acabades en vocal). Els noms **no adaptats** mantenen la grafia d'origen. Les majúscules s'accentuen igual que les minúscules: *Àngel*, *Òscar*, *ÈSQUIL*.", "examples": ["El conferenciant va comparar **Aristòtil** amb **Plató**.", "En la novel·la, el protagonista es diu **Vladímir** i viu a **Kíiv**."]}, {"title": "Topònims", "text": "Els topònims **adaptats** al valencià seguixen les regles generals: *Kíiv* (plana acabada en *-v*), *Hèlsinki*, *Mònaco*, *Còrdova*, *Bogotà*, *Txèquia*; en canvi, *Moscou*, aguda acabada en semivocal, no en porta. Els topònims **no adaptats** es regixen per l'ortografia de la llengua d'origen: *Manchester*, *Düsseldorf*, *São Paulo*, *Alcalá de Henares*.", "watch": [{"wrong": "*Kiiv*, *Helsinki*, *Mónaco*", "right": "Kíiv, Hèlsinki, Mònaco"}, {"wrong": "*Moscoú*", "right": "Moscou"}]}], "remember": ["*Alvèol*, *èczema*, *cotilèdon*, *pneumònia*, *elit*: tònica diferent del castellà.", "*Acne*, *atmosfera*, *medul·la*, *ciclop* i *miop*, sense accent; *etíop*, *monòlit*, *diòptria*, *període*, *timpà*, amb accent.", "*Anèmia*, *leucèmia* (esdrúixoles), però *policia*, *energia*, *cirurgia* (planes).", "Sempre *-íac*: *cardíac*, *policíac*, *amoníac*.", "Noms adaptats, regles generals: *Vladímir*, *Aristòtil*, *Kíiv*, *Hèlsinki*; no adaptats, grafia d'origen."], "sources": [{"gram": "GNV", "section": "5.1.1", "title": "Regles generals d'accentuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=5_1_1"}, {"gram": "GVB", "section": "7.2", "title": "Regles generals d'accentuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=7_2"}, {"gram": "GNV", "section": "1.5", "title": "L'accentuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_5"}, {"gram": "GVB", "section": "3.3", "title": "L'accentuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=3_3"}, {"gram": "GNV", "section": "1.2.1.3", "title": "La distribució de la e i la o obertes", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_2_1_3"}, {"gram": "GVB", "section": "7.10", "title": "L'accentuació de paraules estrangeres", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=7_10"}, {"gram": "GVB", "section": "7.12", "title": "L'accentuació de topònims", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=7_12"}, {"gram": "GVB", "section": "7.13", "title": "L'accentuació de les majúscules", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=7_13"}, {"gram": "GNV", "section": "6.1.1", "title": "Consideracions generals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=6_1_1"}]}},
  {"type": "c2_fon_dieresi", "lesson": {"intro": "Aprendràs a resoldre els casos més difícils de la dièresi: la dièresi en síl·laba àtona, els derivats de paraules amb *i* tònica, els cultismes en *-itzar* i *-itat*, la conjugació de verbs com *argüir*, les parelles que només distingix la dièresi i els casos en què no se'n posa.", "blocks": [{"title": "Dièresi en síl·laba àtona", "text": "La dièresi no indica que la vocal siga tònica, sinó que la *i* o la *u* **no formen diftong** amb la vocal anterior. Per això es manté quan el hiat queda en síl·laba **àtona**: *a-ï-llar*, *tra-ï-ció*, *ve-ï-nat*, *ra-ï-met*, *o-ï-dor*, *ta-ü-ter*, *di-ür-nal*. Si se suprimira, es llegiria un diftong: *aillar* sonaria [aj-ʎáɾ].", "examples": ["L'**aïllament** tèrmic de l'edifici és deficient.", "La novel·la tracta d'una **traïció** entre germans.", "El **veïnat** va recollir firmes contra el projecte."]}, {"title": "Derivats de paraules amb i tònica", "text": "Quan una paraula té una *i* tònica que, en el derivat, queda **en hiat** darrere de vocal, el derivat porta dièresi encara que la base no en porte: *illa* → *aïllar*, *aïllament*; *trair* → *traïdor*, *traïció*. El mateix passa amb *u*: *diürn* → *diürnal*.", "table": {"head": ["base", "derivat amb dièresi"], "rows": [["*illa*", "*aïllar*, *aïllament*, *aïllant*"], ["*trair*", "*traïdor*, *traïció*"], ["*oir*", "*oïdor*"], ["*raïm*", "*raïmet*"]]}}, {"title": "Cultismes en -itzar i -itat", "text": "Els derivats cultes amb ***-itzar***, ***-itat*** i sufixos semblants porten dièresi encara que la paraula primitiva tinga **diftong**: *homogeni* → *homogeneïtzar*, *continu* → *continuïtat*, *arcaic* → *arcaïtzar*, *heroi* → *heroïcitat*, *fluid* → *fluïdesa*, *europeu* → *europeïtat*. En canvi, els sufixos ***-isme*** i ***-ista*** no en duen: compara *continuïtat* amb *continuista*.", "table": {"head": ["amb dièresi", "sense dièresi (-isme, -ista)"], "rows": [["*continuïtat*", "*continuista*"], ["*arcaïtzar*, *arcaïtzant*", "*arcaisme*"], ["*europeïtat*", "*europeista*"]]}, "watch": [{"wrong": "*homogeneitzar*, *continuitat*", "right": "homogeneïtzar, continuïtat"}, {"wrong": "*egoïsme*, *europeïsta*", "right": "egoisme, europeista"}]}, {"title": "Verbs com argüir", "text": "En *argüir* poden concórrer dos dièresis: la de la *u* del grup *gu* + *i* i la de la *i* en hiat. **No s'escriuen mai les dos alhora**: quan la *i* porta dièresi, la *u* no en porta (*arguït*, *arguïx*, *arguïa*, *arguïra*); quan la *i* no en porta, perquè duu accent o perquè és infinitiu, gerundi o futur, la *u* sí que en duu (*argüir*, *argüint*, *argüírem*).", "table": {"head": ["forma", "grafia"], "rows": [["infinitiu, gerundi", "*argüir*, *argüint*"], ["participi", "*arguït*, *arguïda*"], ["present", "*arguïx*, *arguïxen*"], ["imperfet", "*arguïa*, *arguïen*"], ["perfet simple", "*argüírem*"], ["imperfet de subjuntiu", "*arguïra*"], ["futur", "*argüiré*"]]}}, {"title": "Parelles que només distingix la dièresi", "text": "En alguns casos, la dièresi és l'única marca que distingix dos paraules: amb diftong es llig una cosa i amb hiat, una altra. Cal pronunciar-les i escriure-les amb cura.", "table": {"head": ["amb diftong", "amb hiat"], "rows": [["*fluid* (adjectiu i nom: ‘que fluïx’)", "*fluït* (participi de *fluir*)"], ["*fruit* (nom: ‘producte d'una planta’)", "*fruït* (participi de *fruir*, ‘sentir un gran plaer’)"], ["*reina* (‘sobirana’)", "*reïna* (‘resina’)"]]}}, {"title": "Quan no se'n posa", "text": "No es posa dièresi quan la vocal ja porta **accent** (*agraíem*, però *agraïen*; *Lluís*, però *Lluïsa*), en els sufixos *-isme* i *-ista*, en l'infinitiu, el gerundi, el futur i el condicional dels verbs en vocal + *-ir* (*traduir*, *traduint*, *traduiré*), quan hi ha una *h* intercalada (*ahir*, *vehicle*), en les terminacions cultes *-um*, *-us* (*aquàrium*, *Màrius*) i darrere de prefix (*reunió*, *antiinflamatori*). Excepcions: *lluïsme*, *proïsme*, *reüll* i les formes rizotòniques de *reeixir* (*reïx*, *reïsca*).", "watch": [{"wrong": "*agraïem*, *paísos*", "right": "agraíem, països"}, {"wrong": "*traduïr*, *traduïnt*", "right": "traduir, traduint"}, {"wrong": "*reünió*, *aquàrïum*", "right": "reunió, aquàrium"}]}], "remember": ["La dièresi marca hiat, no tonicitat: *aïllar*, *traïció*, *veïnat*.", "Derivats d'*i* tònica en hiat: *illa* → *aïllament*, *trair* → *traïdor*.", "*-itzar*, *-itat*: *homogeneïtzar*, *continuïtat*; però *-isme*, *-ista*: *arcaisme*, *continuista*.", "Mai dos dièresis: *argüir*, *argüint*, *argüírem*, però *arguït*, *arguïx*, *arguïa*, *arguïra*.", "*Fluid/fluït*, *fruit/fruït*, *reina/reïna*.", "Sense dièresi: *agraíem*, *traduint*, *vehicle*, *aquàrium*, *reunió*; però *reüll* i *reïx*."], "sources": [{"gram": "GNV", "section": "5.2", "title": "La dièresi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=5_2"}, {"gram": "GVB", "section": "8.1", "title": "Usos de la dièresi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=8_1"}, {"gram": "GVB", "section": "8.2", "title": "Estalvi en l'ús de la dièresi", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=8_2"}, {"gram": "GNV", "section": "3.2", "title": "Els diftongs", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=3_2"}, {"gram": "GVB", "section": "5.2", "title": "Els diftongs", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=5_2"}, {"gram": "GNV", "section": "5.1.1", "title": "Regles generals d'accentuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=5_1_1"}, {"gram": "GVB", "section": "7.2", "title": "Regles generals d'accentuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=7_2"}]}},
  {"type": "c2_fon_guionet", "lesson": {"intro": "Aprendràs a decidir si una paraula composta, una locució o un derivat s'escriuen junts, separats o amb guionet, a usar el guionet amb préstecs, símbols i relacions entre termes, i a partir paraules a final de línia.", "blocks": [{"title": "Compost o locució: junt o separat", "text": "Un **compost propi** té una estructura fusionada i un significat unitari; un **compost sintagmàtic** manté la forma d'un sintagma i s'escriu separat. Sovint la mateixa seqüència té els dos valors: *maldecap* (‘preocupació’, plural *maldecaps*) i *mal de cap* (‘dolor físic’, plural *mals de cap*); *sobretot* (adverbi: ‘principalment’) i *sobre tot* (preposició + pronom: *opina sobre tot*).", "table": {"head": ["junt", "separat"], "rows": [["*maldecap* (‘preocupació’)", "*mal de cap* (‘dolor físic’)"], ["*sobretot* (‘principalment’)", "*sobre tot* (prep. + pronom)"], ["*filferro*", "*fil d'aram*"], ["*benestar*, *benvingut*, *malacostumar*", "*(estar) de mal humor*"], ["*bocamànega*", "*café teatre*, *vagó restaurant*"]]}}, {"title": "Prefixos, derivats i compostos cults: junts", "text": "Els **prefixos** s'unixen a la paraula sense guionet: *subsecretari*, *infraroig*, *exministre*. També s'escriuen junts els adjectius coordinats amb valor unitari (*hispanoamericà*, *francoalemany*), els compostos amb arrels grecollatines (*grecoromà*), els derivats de numerals (*noucentiste*), els derivats de reduplicatius (*xiu-xiu* → *xiuxiuejar*) i gentilicis com *estatunidenc*. El prefix va **separat** davant d'una locució (*ex alt càrrec*) o d'una paraula amb guionet, majúscula, sigla o xifra (*anti nord-americà*, *ex URSS*, *sub 21*).", "watch": [{"wrong": "*sub-secretari*, *infra-roig*", "right": "subsecretari, infraroig"}, {"wrong": "*nou-centiste*, *xiu-xiuejar*", "right": "noucentiste, xiuxiuejar"}, {"wrong": "*antinord-americà*, *exURSS*", "right": "anti nord-americà, ex URSS"}]}, {"title": "Compostos amb guionet", "text": "Porten guionet, entre altres, els compostos amb un **punt cardinal** i els seus derivats (*nord-est*, *sud-africà*, *Sud-àfrica*), els **reduplicatius** (*bum-bum*, *xano-xano*), els patrimonials amb el primer element **accentuat** (*despús-ahir*, *despús-demà*), els que tenen el segon element començat per ***r-***, ***s-*** o ***x-*** darrere de vocal (*vila-realenc*, *gira-sol*) i el *no* lexicalitzat com a prefix (*el no-res*, *la no-violència*; però *per no res*). També *cotó-en-pèl* i *anglo-nord-americà*, que conté un compost amb guionet.", "table": {"head": ["cas", "exemples"], "rows": [["punt cardinal", "*Sud-àfrica*, *nord-est*, *sud-americà*"], ["reduplicació", "*bum-bum*, *xano-xano*, *ping-pong*"], ["primer element accentuat", "*despús-ahir*, *pèl-roig*"], ["*r-*, *s-*, *x-* darrere de vocal", "*vila-realenc*, *gira-sol*, *para-xocs*"], ["*no* lexicalitzat", "*el no-res*, *pacte de no-agressió*"]]}}, {"title": "Préstecs: adaptats junts, no adaptats amb guionet", "text": "Els préstecs **adaptats** s'escriuen junts i en redona: *exlibris*, *agnusdei*. Els **no adaptats** van en cursiva i porten guionet tant si l'escriuen així en la llengua d'origen (*prêt-à-porter*) com si allí tenen els components separats (*déjà-vu*, *hip-hop*). Altres exemples: *dalai-lama*, *pied-noir*, *fox-terrier*.", "examples": ["En la biblioteca conserven un **exlibris** del segle xviii.", "Va tindre la sensació d'un ***déjà-vu*** en entrar a la sala.", "La col·lecció de ***prêt-à-porter*** es va presentar a València."]}, {"title": "Formes estranyes, relacions i símbols", "text": "El guionet evita **formes estranyes** o de lectura difícil: *cul-de-sac*, *qui-sap-lo*, *Bell-lloc*, *pit-roig*. També funciona com a **recurs sintàctic** per a expressar una relació o una direcció entre dos termes que es mantenen invariables: *relació qualitat-preu*, *míssil terra-aire*, *el trajecte València-Alacant*, *pàgines 250-278*. En els llenguatges d'especialitat unix un **símbol** o una **xifra** a la paraula: *α-naftol*, *àcid d-lisèrgic*, *goma-2*.", "examples": ["És un hotel amb una bona **relació qualitat-preu**.", "Hi havia **qui-sap-la** gent esperant a la porta.", "El laboratori treballa amb **α-naftol**."]}, {"title": "Partició de paraules a final de línia", "text": "Per a partir una paraula a final de línia, se separen els dígrafs i lletres compostes *rr*, *ss*, *sc*, *l·l*, *tj*, *tg*, *tx*, *tl*, *tll*, *tm*, *tn*, *tz*, *mm* i *nn* (*car-rer*, *set-mana*, *rot-llo*), però **mai** *gu*, *ny*, *qu*, *ig* i *ll*. En els compostos i els derivats amb prefix es respecten els constituents (*ben-estar*, *des-encolar*, *in-expert*, *vos-altres*), i no es deixa cap lletra sola a final o a començament de línia (*l'a-plicació*, *histò-ria*).", "table": {"head": ["regla", "correcte", "incorrecte"], "rows": [["dígraf separable", "*pas-sar*, *rot-llo*", "*pa-ssar*, *ro-tllo*"], ["dígraf inseparable", "*pe-nya*, *pa-quet*", "*pen-ya*, *paq-uet*"], ["prefix o compost", "*des-encolar*, *ben-estar*", "*de-sencolar*, *be-nestar*"], ["lletra sola", "*aber-rant*, *histò-ria*", "*a-berrant*, *històri-a*"]]}}], "remember": ["*Maldecap*/*mal de cap*, *sobretot*/*sobre tot*, *filferro*/*fil d'aram*, *bocamànega*/*café teatre*.", "Prefixos junts (*subsecretari*, *infraroig*), però separats davant de locució o element gràfic (*ex alt càrrec*, *ex URSS*).", "Guionet: *Sud-àfrica*, *despús-ahir*, *vila-realenc*, *el no-res*, *bum-bum*, *cotó-en-pèl*.", "Préstecs adaptats junts (*exlibris*, *agnusdei*); no adaptats amb guionet (*prêt-à-porter*, *déjà-vu*, *hip-hop*).", "*Cul-de-sac*, *qui-sap-lo*, *relació qualitat-preu*, *α-naftol*, *goma-2*.", "A final de línia: mai partir *gu*, *ny*, *qu*, *ig*, *ll*, ni deixar una lletra sola."], "sources": [{"gram": "GNV", "section": "5.3", "title": "El guionet", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=5_3"}, {"gram": "GVB", "section": "9.1", "title": "Usos del guionet", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=9_1"}, {"gram": "GVB", "section": "9.2", "title": "Casos sense guionet", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=9_2"}, {"gram": "GNV", "section": "38.2", "title": "La composició", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=38_2"}, {"gram": "GNV", "section": "38.3", "title": "La composició sintagmàtica", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=38_3"}, {"gram": "GNV", "section": "38.4.1", "title": "La reduplicació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=38_4_1"}, {"gram": "GNV", "section": "3.1.2", "title": "Normes de separació sil·làbica", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=3_1_2"}, {"gram": "GVB", "section": "5.1.2", "title": "Normes de separació sil·làbica", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=5_1_2"}, {"gram": "GNV", "section": "6.2.2", "title": "La cursiva", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=6_2_2"}]}},
  {"type": "c2_fon_apostrofacio", "lesson": {"intro": "Aprendràs a apostrofar l'article davant de sigles i acrònims, a resoldre la contracció i l'apostrofació amb topònims i noms d'institucions, i a reconéixer les excepcions: articles que formen part d'un nom propi, *h* aspirada, noms de lletres i signes, i usos metalingüístics.", "blocks": [{"title": "Sigles: com es lligen?", "text": "Davant d'una sigla, l'apostrofació depén de com es **pronuncia**. Si es llig com una paraula (sigla **sil·làbica**), s'apliquen les regles generals: *l'IVAM*, *l'ONU*, *l'UJI*, però *la UNESCO* i *la UEFA*, amb *u* inicial semivocal o àtona. Si es **lletreja**, es tracta com si estiguera escrita amb el nom de les lletres: *l'ONG* (‘oenegé’), *l'FMI* (‘efeemeí’), però *la ITV* (‘itevé’, amb *i* àtona).", "table": {"head": ["sigla", "lectura", "article"], "rows": [["*IVAM*", "com una paraula", "*l'IVAM*"], ["*UEFA*", "com una paraula", "*la UEFA*"], ["*FMI*", "efe-ema-i", "*l'FMI*"], ["*ITV*", "i-te-ve", "*la ITV*"], ["*IBM*", "i-be-ema", "*la IBM*"]]}}, {"title": "Acrònims i gènere de les sigles", "text": "Els **acrònims** (formats amb grups de lletres) es poden escriure tot en majúscula o només amb la inicial (*IVAJ* o *Ivaj*, Institut Valencià de la Joventut) i s'apostrofen com qualsevol paraula: *l'IVAJ*. El gènere de la sigla és el de la **primera paraula** desplegada (*el KGB*, *la CIA*, *els EUA*) o el d'un nom genèric sobreentés: *la IBM* (l'empresa).", "watch": [{"wrong": "*el IVAM*, *el IVAJ*", "right": "l'IVAM, l'IVAJ"}, {"wrong": "*l'UEFA*, *l'IBM*", "right": "la UEFA, la IBM"}, {"wrong": "*el FMI*, *l'ITV*", "right": "l'FMI, la ITV"}]}, {"title": "Contraccions amb topònims i institucions", "text": "L'article dels **topònims valencians** s'escriu en minúscula i es contrau o s'apostrofa amb normalitat: *ve del Puig*, *va al Campello*, *la capital del Maestrat*, *la comarca de l'Alacantí*, *ix de l'Eliana*. En els noms d'**institucions**, l'article no forma part del nom i, per tant, també es contrau: *del Consell de Presidència*, *al Museu de Belles Arts*.", "examples": ["Este autobús ve **del Puig** i para **al Campello**.", "Estes cartes són **del Consell de Presidència**.", "La capital **de l'Alacantí** és Alacant."]}, {"title": "Quan l'article forma part del nom", "text": "Si l'article forma part d'un **nom propi** (empreses, títols, grups, publicacions) o d'un **topònim no adaptat**, s'escriu en majúscula i no es contrau. La preposició *de* s'apostrofa si la paraula següent comença per vocal: *d'El Corte Inglés*, *d'El Senyor dels Anells*.", "table": {"head": ["cas", "forma correcta"], "rows": [["empresa", "*el supermercat d'El Corte Inglés*"], ["títol", "*este fragment és d'El Senyor dels Anells*"], ["publicació", "*està subscrit a El Punt*"], ["topònim no adaptat", "*la ciutat d'El Paso*, *un viatge a El Salvador*"]]}, "watch": [{"wrong": "*del Corte Inglés*", "right": "d'El Corte Inglés"}, {"wrong": "*al Salvador*", "right": "a El Salvador"}]}, {"title": "Excepcions a l'apostrofació", "text": "No s'apostrofa davant de *h* **aspirada** (*són originaris de Hawaii*, *una actriu de Hollywood*) ni davant de *i*, *u* semivocals (*el iogurt*, *de hui*). L'article *la* i la preposició *de* mantenen la forma plena davant del **nom de les lletres** (*la a*, *la hac*, *davant de eme*), i el Quadern C2 recull també la forma plena davant del signe ***@*** (*cal escriure sempre la @*). L'article *la* tampoc s'apostrofa davant de *una* (l'hora), *ira* i *host*. Davant d'una paraula usada amb valor **metalingüístic** és preferible la forma plena: *el plural de home és hòmens o homes*.", "watch": [{"wrong": "*d'Hawaii*, *d'Hollywood*", "right": "de Hawaii, de Hollywood"}, {"wrong": "*l'@*", "right": "la @"}, {"wrong": "*el plural d'home*", "right": "el plural de home"}]}], "remember": ["Sigles: apostrofació segons la lectura: *l'IVAM*, *l'FMI*, però *la UEFA*, *la ITV*, *la IBM*.", "Acrònims com paraules: *l'IVAJ* o *l'Ivaj*; gènere de la primera paraula o del genèric.", "Topònims valencians i institucions: *del Puig*, *al Campello*, *del Maestrat*, *del Consell*.", "Article dins del nom propi o topònim no adaptat, sense contracció: *d'El Corte Inglés*, *a El Salvador*.", "Formes plenes: *de Hawaii*, *la @*, *la hac*, *el plural de home*."], "sources": [{"gram": "GNV", "section": "5.4", "title": "L'apòstrof", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=5_4"}, {"gram": "GVB", "section": "10.2", "title": "L'apostrofació de l'article definit", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_2"}, {"gram": "GVB", "section": "10.5", "title": "L'Apostrofació davant de i o u no vocàliques", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_5"}, {"gram": "GVB", "section": "10.6", "title": "L'apostrofació davant de h aspirada", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_6"}, {"gram": "GVB", "section": "10.8", "title": "L'apostrofació davant de paraules homòfones", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_8"}, {"gram": "GVB", "section": "10.9", "title": "L'apostrofació davant del nom de les lletres", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_9"}, {"gram": "GVB", "section": "10.10", "title": "L'apostrofació davant de cometes o cursiva", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_10"}, {"gram": "GVB", "section": "10.13", "title": "L'apostrofació davant de sigles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_13"}, {"gram": "GVB", "section": "11.1", "title": "Formació de les contraccions", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=11_1"}, {"gram": "GVB", "section": "11.2", "title": "Descomposició de les contraccions", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=11_2"}, {"gram": "GNV", "section": "6.3.3", "title": "Les sigles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=6_3_3"}, {"gram": "GVB", "section": "14.4.1", "title": "Escriptura de les sigles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=14_4_1"}, {"gram": "GVB", "section": "12.25", "title": "Noms de lloc", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=12_25"}]}},
  {"type": "c2_fon_oclusives_bv", "lesson": {"intro": "Aprendràs a pronunciar i escriure les oclusives en els casos més complexos: els grups *cap-* i *prop-*, els grups cultes inicials amb consonant muda, les duplicacions gràfiques, els préstecs i els noms propis, i la *b* i la *v* en pseudoderivats i topònims.", "blocks": [{"title": "Grups cap- i prop-", "text": "La síl·laba inicial *cap-* s'escriu generalment amb *p* (*capçal*, *captiu*, *capdavanter*), tot i que alguns mots duen *b* (*cabdal*, *cabdell*, *cabdill*). La grafia no canvia, però la pronúncia sí: davant de consonant sonora la *p* es fa sonora, *capdavanter* [kabdavantéɾ], i davant de *m* es pronuncia [bm] o [mm] (*capmoix* [kabmójʃ]). En *proppassat* les dos *p* es pronuncien: pro[pp]assat.", "table": {"head": ["paraula", "pronúncia"], "rows": [["*capdavanter*", "ca[bd]avanter"], ["*capmoix*, *Capmany*", "ca[bm]oix o ca[mm]oix (preferible [bm])"], ["*proppassat*", "pro[pp]assat"], ["*cabdal*, *cabdell*", "amb *b* escrita"]]}}, {"title": "Grups cultes inicials i paraules difícils", "text": "En els grups cultes ***pn-***, ***ps-***, ***pt-*** i ***ts-*** a començament de paraula, la primera consonant **no es pronuncia**: *pneumàtic* [newmátik], *pneumologia*, *pseudònim* [sewðɔ́nim], *psiquiatre* [sikiátɾe], *pterodàctil* [teɾoðáktil], *ptolemaic*, *tsarista* [saɾísta], *tsunami* [sunámi]. Només en registres molt formals es pronuncien *ps-* i *ts-*. Altres paraules demanen atenció: *apotegma* (amb *g* davant de *m*), *babord* (amb *d* final), *molibdé* i *tungsté* [tuŋsté], amb *é* final (també *molibdè*, *tungstè*).", "watch": [{"wrong": "*neumàtic*, *seudònim*, *siquiatre*", "right": "pneumàtic, pseudònim, psiquiatre"}, {"wrong": "*apotecma*, *babor*", "right": "apotegma, babord"}]}, {"title": "Duplicacions gràfiques", "text": "Algunes paraules tenen dos consonants iguals o semblants seguides. No totes es pronuncien igual: en *subbranquial* sonen les dos *b*; en *addició* només sona una *d*; en *accèssit* i *aflicció*, *cc* val [ks]; en *suggestió* la primera *g* és muda, i en *sangglaçar-se* la *n* es fa velar i la primera *g* no sona.", "table": {"head": ["paraula", "pronúncia"], "rows": [["*subbranquial*", "su[bb]ranquial"], ["*addició*", "a[d]ició"], ["*accèssit*, *aflicció*", "a[ks]èssit, afli[ks]ió"], ["*suggestió*, *suggerir*", "su[ʤ]estió, su[ʤ]erir"], ["*sangglaçar-se*", "sa[ŋg]laçar-se"]]}, "watch": [{"wrong": "*adició*, *sugestió*", "right": "addició, suggestió"}, {"wrong": "*acèssit*, *aflició*", "right": "accèssit, aflicció"}]}, {"title": "Oclusives en préstecs i noms propis", "text": "En els préstecs, la grafia de l'oclusiva final no sempre seguix la regla general: *grog* s'escriu amb *g* com *buldog* o *demagog*, i en *màrqueting* la *-ng* final sona [ŋ], sense *g*. Alguns préstecs conserven la *k* (*judoka*, *karate*). En els noms propis cal recordar la consonant final o la grafia pròpia: els topònims *Carib*, *Qatar*, *Iraq* i els antropònims *Caleb*, *Abelard*, *Eduard*, *Hug*. Com qualsevol oclusiva final, sonen sordes davant de pausa: *Hu*[k], *Eduar*[t].", "examples": ["Van servir un **grog** calent després de l'excursió.", "El departament de **màrqueting** prepara la campanya.", "**Hug** i **Eduard** van viatjar al **Carib**."], "watch": [{"wrong": "*grok*, *marketing*", "right": "grog, màrqueting"}, {"wrong": "*Caribe*, *Hugo*", "right": "Carib, Hug"}]}, {"title": "b i v: pseudoderivats i topònims", "text": "S'escriu *b* davant de *l* i *r*, darrere de *m* i quan alterna amb *p* (*cabut*, *saber*); s'escriu *v* darrere de *n*, quan alterna amb *u* (*blava*, *escriviu*) i en l'imperfet *-ava*. Però paraules de la mateixa família poden alternar *b* i *v* pel tractament **patrimonial** o **culte**: *avortar* / *abortiu*, *calb* / *calvície*, *cervell* / *cerebral*, *berruga* / *verrucària*. Alguns topònims tenen en valencià una grafia diferent de la castellana.", "table": {"head": ["valencià", "castellà"], "rows": [["*Àlaba*", "*Álava*"], ["*Anvers*", "*Amberes*"], ["*Biscaia*", "*Vizcaya*"], ["*l'Havana*", "*La Habana*"], ["*Nerbion*", "*Nervión*"], ["*Còrdova*", "*Córdoba*"]]}, "watch": [{"wrong": "*abortar*, *avortiu*", "right": "avortar, abortiu"}, {"wrong": "*verruga*, *berrucària*", "right": "berruga, verrucària"}]}], "remember": ["*Capdavanter* ca[bd]avanter, *proppassat* pro[pp]assat; però *cabdal*, *cabdell* amb *b*.", "Consonant inicial muda: *pneumàtic*, *pseudònim*, *psiquiatre*, *pterodàctil*, *tsunami*.", "*Apotegma*, *babord*, *molibdé*, *tungsté* [tuŋsté].", "*Subbranquial*, *addició*, *accèssit*, *aflicció*, *suggestió*, *sangglaçar-se*.", "*Grog*, *màrqueting*, *judoka*; *Carib*, *Qatar*, *Iraq*; *Caleb*, *Abelard*, *Eduard*, *Hug*.", "*Avortar/abortiu*, *berruga/verrucària*; *Àlaba*, *Anvers*, *Biscaia*, *l'Havana*, *Nerbion*."], "sources": [{"gram": "GNV", "section": "4.9", "title": "Les grafies b i p", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_9"}, {"gram": "GVB", "section": "6.7", "title": "Les grafies b i p", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_7"}, {"gram": "GNV", "section": "4.11", "title": "Les grafies d i t", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_11"}, {"gram": "GNV", "section": "4.1", "title": "La representació dels sons [g] i [k]", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_1"}, {"gram": "GVB", "section": "6.5", "title": "Les grafies g i c", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_5"}, {"gram": "GNV", "section": "4.10", "title": "Les grafies b i v", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_10"}, {"gram": "GVB", "section": "6.24", "title": "Les grafies b i v", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_24"}, {"gram": "GNV", "section": "1.3.2.1", "title": "Les consonants oclusives", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_1"}, {"gram": "GVB", "section": "2.1.1", "title": "Pronunciacions recomanables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_1_1"}, {"gram": "GNV", "section": "1.3.2.7", "title": "Les consonants nasals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_7"}, {"gram": "GNV", "section": "1.3.2.3", "title": "Les consonants sibilants alveolars", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_3"}, {"gram": "GNV", "section": "1.4.2.1", "title": "Les consonants oclusives en posició final", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_4_2_1"}]}},
  {"type": "c2_fon_alveolars", "lesson": {"intro": "Aprendràs a escriure i pronunciar les consonants alveolars en cultismes i noms propis complexos, en paraules derivades amb prefix i en compostos, i a usar bé les grafies *tz* i *ts*.", "blocks": [{"title": "Cultismes i noms propis d'especial complexitat", "text": "Algunes paraules d'ús formal i alguns noms propis tenen una grafia alveolar que no coincidix amb la del castellà. Cal fixar-se en la *s*, la *ss*, la *c* i la *ç*, i també en la pronúncia: en *desembre* la *s* intervocàlica és sonora [z], i en *èczema* el grup *cz* sona [gz].", "table": {"head": ["valencià", "pronúncia o grafia", "castellà"], "rows": [["*desembre*", "de[z]embre", "*diciembre*"], ["*èczema*", "è[gz]ema", "*eccema*"], ["*Ignasi*", "amb *s*", "*Ignacio*"], ["*Saragossa*", "*S* inicial i *ss*", "*Zaragoza*"], ["*Moçambic*", "amb *ç*", "*Mozambique*"], ["*Ademús*", "amb *s* final", "*Ademuz*"], ["*sentinella* (o *sentinel·la*)", "amb *s* inicial", "*centinela*"]]}, "watch": [{"wrong": "*dicembre*, *Ignaci*", "right": "desembre, Ignasi"}, {"wrong": "*Zaragossa*, *Mozambic*", "right": "Saragossa, Moçambic"}]}, {"title": "Alveolars darrere de prefix i en compostos", "text": "Darrere de prefixos i formes prefixades acabats en vocal, la [s] de la paraula base s'escriu amb **una sola *s*** encara que quede entre vocals: *asimetria* a[s]imetria, *antisocial*, *contrasenya* contra[s]enya, *multisecular*, *dinosaure*. En els compostos amb guionet passa el mateix: *esclata-sang*, *para-sol*. Quan el prefix acaba en *-s* (*trans-*, *sots-*) i la base comença per *s*, s'escriu ***ss*** darrere de consonant: *transsiberià* tra[ns]iberià, *transsexual*, *sotssecretari*. Alguns derivats lexicalitzats s'escriuen amb *ss* intervocàlica: *pressentir* pre[s]entir, *pressuposar*, *ressorgir*.", "table": {"head": ["cas", "exemples"], "rows": [["prefix + *s* (una *s*, so [s])", "*asimetria*, *contrasenya*, *antisocial*, *presocràtic*"], ["*trans-*, *sots-* + *s*", "*transsiberià*, *sotssecretari*"], ["derivats lexicalitzats amb *ss*", "*pressentir*, *pressuposar*, *ressorgir*"], ["*trans-*, *fons*, *dins* + vocal (so [z])", "*transatlàntic*, *enfonsar*, *endinsar*"]]}, "watch": [{"wrong": "*assimetria*, *contrassenya*", "right": "asimetria, contrasenya"}, {"wrong": "*transiberià*, *presentir* (‘intuir’)", "right": "transsiberià, pressentir"}]}, {"title": "La z intervocàlica i altres casos", "text": "Entre vocals el so [z] s'escriu normalment amb *s* (*casa*, *revisió*), però alguns préstecs i cultismes s'escriuen amb ***z***: *bizantí*, *protozou*, *nazisme*, *buldòzer*. En posició inicial i darrere de consonant s'escriu *z* (*zebra*, *pinzell*), excepte en els derivats de *fons*, *dins* i *trans*. En final de paraula s'escriu *s*, excepte en alguns préstecs (*hertz*) i en *brunz*, que manté la *z* de *brunzir* tot i sonar [s].", "examples": ["L'art **bizantí** destaca pels mosaics.", "Les obres requerien un **buldòzer** per a moure la terra.", "Es va sentir el **brunz** d'un insecte."]}, {"title": "Les grafies tz i ts", "text": "La grafia ***tz*** representa [dz] en paraules patrimonials (*dotze*, *tretze*, *setze*, mai [ʤ]) i [z] en els verbs en *-itzar* i derivats (*analitzar*, *realització*), i també en *zitzània* zi[z]ània. La grafia ***ts*** sona [ʦ] en *sotsobrar* so[ʦ]obrar i en els derivats amb *sots-* + *s* (*sotssecretari*); en posició inicial sona [s] (*tsar* [sáɾ]), i en final de paraula s'ha de pronunciar [ts], no [ʧ] (*plats*, *molts*).", "table": {"head": ["grafia", "exemple", "pronúncia"], "rows": [["*tz* patrimonial", "*setze*", "se[dz]e"], ["*tz* de *-itzar*", "*analitzar*", "anali[z]ar"], ["*tz* en *zitzània*", "*zitzània*", "zi[z]ània"], ["*ts* interior", "*sotsobrar*", "so[ʦ]obrar"], ["*ts-* inicial", "*tsarista*", "[s]arista"]]}, "watch": [{"wrong": "*se[ʤ]e*, *tre[ʤ]e*", "right": "se[dz]e, tre[dz]e"}, {"wrong": "*pla[ʧ]*, *mol[ʧ]*", "right": "pla[ts], mol[ts]"}]}], "remember": ["*Desembre* de[z]embre, *èczema* è[gz]ema, *Ignasi*, *Saragossa*, *Moçambic*, *Ademús*, *sentinella*.", "Darrere de prefix, una *s*: *asimetria*, *contrasenya*, *multisecular*.", "*Trans-* o *sots-* + *s*: *transsiberià*, *sotssecretari*; i *pressentir*, *pressuposar*, *ressorgir*.", "*Z* intervocàlica en préstecs i cultismes: *bizantí*, *nazisme*, *buldòzer*.", "*Tz*: *setze* [dz], *analitzar* [z], *zitzània* [z]; *ts*: *sotsobrar* [ʦ], *tsar* [s], *plats* [ts]."], "sources": [{"gram": "GNV", "section": "4.2.1", "title": "La grafia s", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_2_1"}, {"gram": "GNV", "section": "4.2.2", "title": "La grafia ss", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_2_2"}, {"gram": "GNV", "section": "4.2.3", "title": "Les grafies c i ç", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_2_3"}, {"gram": "GNV", "section": "4.3", "title": "La representació del so [z]: les grafies s i z", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_3"}, {"gram": "GNV", "section": "4.4", "title": "La grafia tz", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_4"}, {"gram": "GNV", "section": "1.3.2.3", "title": "Les consonants sibilants alveolars", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_3"}, {"gram": "GVB", "section": "6.13", "title": "Les grafies s i ss", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_13"}, {"gram": "GVB", "section": "6.14", "title": "Les grafies ç i c", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_14"}, {"gram": "GVB", "section": "6.15", "title": "Les grafies z i s", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_15"}, {"gram": "GVB", "section": "6.16", "title": "La grafia tz", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_16"}, {"gram": "GVB", "section": "2.3.1", "title": "Pronunciacions recomanables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_3_1"}, {"gram": "GVB", "section": "2.3.2", "title": "Pronunciacions no recomanables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_3_2"}, {"gram": "GNV", "section": "4.8", "title": "La representació del grup fònic [ks]", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_8"}]}},
  {"type": "c2_fon_palatals", "lesson": {"intro": "Aprendràs a escriure les consonants palatals en tots els casos, inclosos els de més dificultat: la distribució de *x*, *tx*, *ig* i *g*; de *g*, *j*, *tg* i *tj*; la *x* de [ʃ]; les palatals laterals i nasals, i les palatals dels préstecs i dels noms propis, amb el *tx-* inicial excepcional.", "blocks": [{"title": "El so [ʧ]: x, tx, ig i g", "text": "El so [ʧ] s'escriu ***x*** a començament de paraula (*xafar*, *Xelva*) i darrere de consonant (*anxova*, *perxa*, *ponx*, *Elx*); ***tx*** entre vocals (*clòtxina*, *pitxer*). En final de paraula darrere de vocal, s'escriu ***tx*** si els derivats tenen *tx*, i ***ig*** (darrere de *a*, *e*, *o*, *u*) o ***g*** (darrere de *i*) si els derivats tenen *j*, *g*, *tj* o *tg*.", "table": {"head": ["final", "derivat"], "rows": [["*despatx*, *capritx*, *cartutx*", "*despatxar*, *encapritxar-se*, *cartutxera*"], ["*bateig*, *roig*", "*batejar*, *roja*"], ["*desig*", "*desitjar*"]]}, "watch": [{"wrong": "*capritxo*, *despaig*", "right": "capritx, despatx"}, {"wrong": "*desitx*, *batetx*", "right": "desig, bateig"}]}, {"title": "El so [ʤ]: g, j, tg i tj", "text": "S'escriu ***g*** davant de *e*, *i* (*àngel*, *àgil*) i ***j*** davant de *a*, *o*, *u* (*penjar*, *jove*). Per raons etimològiques s'escriu *j* davant de *e* en *jerarquia*, *jeroglífic*, *jersei*, *jesuïta*, *majestat* i en els grups *-ecc-*, *-ect-* (*injecció*, *objecte*). Entre vocals poden aparéixer ***tg*** (davant de *e*, *i*: *coratge*, *paisatgístic*) i ***tj*** (davant de *a*, *o*, *u*: *desitjar*, *pitjor*, *corretjut*). En l'estàndard el so és africat **sonor**: *fetge* [féʤe], no [féʧe]; i la *j* de *projecció* o *trajecte* no es pronuncia [j].", "watch": [{"wrong": "*gerarquia*, *gersei*, *magestat*", "right": "jerarquia, jersei, majestat"}, {"wrong": "*fe[ʧ]e*, *pla[ʧ]a*", "right": "fe[ʤ]e, pla[ʤ]a"}, {"wrong": "*pro[j]ecció*, *tra[j]ecte*", "right": "pro[ʤ]ecció, tra[ʤ]ecte"}]}, {"title": "El so [ʃ] i les palatals ll i ny", "text": "El so [ʃ] s'escriu sempre amb ***x***: *Xàtiva*, *xenòfob*, *coixí*, *dibuix*. No s'ha de pronunciar [s] (*abaixar*, *cuixa*) ni afegir-hi una vocal davant (*Xàtiva*, no [ajʃátiva]). El so [ʎ] s'escriu ***ll*** i, en alguns mots, ***tll*** (*bitllet*, *rotllo*), que sona [ʎ] simple; el so [ɲ] s'escriu sempre ***ny*** (*nyora*, *codony*). Cal evitar la *l* palatalitzada en cultismes (*lectura*, *literatura*), tot i que alguns admeten les dos grafies: *liberal* o *lliberal*.", "watch": [{"wrong": "*abai[s]ar*, *cui[s]a*", "right": "abai[ʃ]ar, cui[ʃ]a"}, {"wrong": "*[ʎ]iteratura*, *[ʎ]ectura*", "right": "[l]iteratura, [l]ectura"}]}, {"title": "Palatals en préstecs i tx- inicial", "text": "Les paraules adaptades d'altres llengües s'escriuen amb les grafies palatals del valencià: *haixix* [ajʃíʃ], amb *h* muda i *x* de [ʃ]. Excepcionalment, el so [ʧ] s'escriu ***tx*** a començament de paraula en alguns mots i noms propis d'altres llengües, i també darrere de consonant en alguns noms (*Khruixtxov*). En majúscula només va la primera lletra del dígraf: *Txad*, no *TXad*.", "table": {"head": ["tx- inicial", "exemples"], "rows": [["topònims", "*Txad*, *Txèquia*"], ["gentilicis", "*txadià*, *txec*, *txeca*, *txetxé* (o *txetxè*)"], ["antropònims", "*Txaikovski*"], ["noms comuns", "*txa-txa-txa*"]]}, "watch": [{"wrong": "*xec* (‘de Txèquia’), *Chad*", "right": "txec, Txad"}, {"wrong": "*hatxís*, *Chaikovski*", "right": "haixix, Txaikovski"}]}], "remember": ["[ʧ]: *x* inicial i darrere de consonant, *tx* entre vocals; final *tx*, *ig* o *g* segons els derivats (*despatx*, *roig*, *desig*).", "*J* davant de *e* en *jerarquia*, *jeroglífic*, *jersei*, *majestat*, *injecció*, *objecte*.", "*Tg*/*tj* intervocàliques (*coratge*, *pitjor*) i [ʤ] sonora: *fetge* [féʤe].", "[ʃ] sempre *x*: *Xàtiva*, *xenòfob*; *tll* sona [ʎ]: *bitllet*.", "*Haixix*; *tx-* inicial excepcional: *Txad*, *txadià*, *Txèquia*, *txec*, *txetxé*, *Txaikovski*, *txa-txa-txa*."], "sources": [{"gram": "GNV", "section": "4.5", "title": "La representació del so [ʤ]: les grafies g, j, tg i tj", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_5"}, {"gram": "GNV", "section": "4.6", "title": "La representació del so [ʧ]: les grafies x, tx, ig i g", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_6"}, {"gram": "GNV", "section": "4.7", "title": "La representació del so [ʃ]: la grafia x", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_7"}, {"gram": "GNV", "section": "1.3.2.4", "title": "Les consonants sibilants palatals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_4"}, {"gram": "GVB", "section": "6.10", "title": "Les grafies j i g", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_10"}, {"gram": "GVB", "section": "6.11", "title": "Les grafies tj i tg", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_11"}, {"gram": "GVB", "section": "6.12", "title": "Les grafies x, tx i ig", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_12"}, {"gram": "GVB", "section": "2.4.3", "title": "Pronunciacions no recomanables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_4_3"}, {"gram": "GNV", "section": "4.13", "title": "La grafia ny", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_13"}, {"gram": "GNV", "section": "4.15", "title": "Les grafies ll i tll", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_15"}, {"gram": "GNV", "section": "1.3.2.5", "title": "Les consonants laterals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_5"}, {"gram": "GVB", "section": "6.18", "title": "Les grafies ll i tll", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_18"}, {"gram": "GNV", "section": "6.1.1", "title": "Consideracions generals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=6_1_1"}]}},
  {"type": "c2_fon_laterals_nasals", "lesson": {"intro": "Aprendràs a escriure la *-l* final en paraules difícils, la *tl* geminada valenciana i les parelles amb *l* i *l·l*, i les regles avançades de les nasals: *m* o *n* davant de *b*, *p*, *f*, *v* i *r*, *-n* i *-m* finals, i els grups *mm*, *nn*, *nm* i *mn*.", "blocks": [{"title": "-l final en paraules difícils", "text": "Algunes paraules acaben en ***-l*** on el castellà té una vocal final o una altra terminació: *bonítol* (cast. *bonito*), *cerebel* (*cerebelo*), *cérvol* o *cervo* (*ciervo*), *nínxol* (*nicho*). Com que *bonítol*, *nínxol* i *cérvol* són planes acabades en consonant, porten accent; *cérvol* s'escriu sempre amb accent tancat. *Cerebel* és aguda acabada en *-l* i no en duu.", "examples": ["Van pescar un **bonítol** prop del port de Dénia.", "El **cerebel** coordina els moviments del cos.", "A la serra hi havia un **cérvol** que menjava herba."], "watch": [{"wrong": "*bonito* (peix), *cerebelo*", "right": "bonítol, cerebel"}, {"wrong": "*nitxo*, *cèrvol*", "right": "nínxol, cérvol"}]}, {"title": "tl geminada, l·l i parelles amb laterals", "text": "La grafia ***tl*** de paraules patrimonials representa una geminada, que és la **pronúncia preferent**: *batle* [bálle], *butla* [búlla], *ametla*, *guatla*, *motle*, *vetlar*. En cultismes, *tl* sona [dl] (o [ll]): *atles*, *atleta*. La ***l·l*** apareix per etimologia en cultismes (*il·lusió*, *col·laborar*, *síl·laba*) i sona com una *l* simple, excepte en registres molt formals. Per això hi ha **homòfons** que només distingix l'escriptura: *vila* (‘població’) i *vil·la* (‘casa d'estiueig voltada de jardí’), totes dos [víla].", "table": {"head": ["grafia", "exemples", "pronúncia"], "rows": [["*tl* patrimonial", "*batle*, *butla*, *ametla*", "[ll] (o [l])"], ["*tl* culte", "*atleta*, *atlàntic*", "[dl] (o [ll])"], ["*l·l*", "*vil·la*, *il·lusió*", "[l] (molt formal: [ll])"], ["*tll*", "*bitllet*, *butlletí*", "[ʎ]"]]}}, {"title": "m o n davant de b, p, f, v i r", "text": "Davant de *b*, *p* i *m* s'escriu *m* (*símbol*, *omplir*, *immigrant*), però es manté la *n* dels prefixos i dels primers constituents de compostos: *enmig*, *benparlat*, *entornpeu*. Davant de ***f*** s'escriu *m* (*àmfora*, *amfiteatre*, *nimfa*), però *n* en les paraules començades per *con-*, *in-* i la majoria de les començades per *en-*: *confegir*, *infermer*, *enfadar*, *enfortir*. En tots els casos, davant de *f* la nasal es pronuncia labiodental [ɱ]: e[ɱ]fadar, à[ɱ]fora. Davant de ***v*** s'escriu *n* (*convent*, *recanvi*), excepte *circumval·lació*, *tramvia*, *triumvir*. Davant de ***r*** s'escriu *n* en *Enric* o *honrat*, però *m* en *somriure* i *somrís*.", "table": {"head": ["context", "m", "n"], "rows": [["davant de *f*", "*àmfora*, *amfiteatre*", "*enfadar*, *confegir*, *infermer*"], ["davant de *b*, *p*", "*símbol*, *omplir*", "*benparlat*, *entornpeu*"], ["davant de *v*", "*tramvia*, *triumvir*", "*convent*, *recanvi*"], ["davant de *r*", "*somriure*, *somrís*", "*Enric*, *honrat*"]]}}, {"title": "-n i -m finals", "text": "En final de paraula, la nasal es pronuncia i cal escriure la que correspon, que sovint no coincidix amb la del castellà: *tron*, *orangutan* amb *-n*; *betum* (cast. *betún*) amb *-m*, com les paraules patrimonials *fum*, *ham* o *nom*.", "examples": ["El rei va abdicar i va deixar el **tron**.", "L'**orangutan** viu en els boscos de Borneo i Sumatra.", "Va enllustrar les sabates amb **betum**."], "watch": [{"wrong": "*betun*, *orangutà*", "right": "betum, orangutan"}]}, {"title": "Grups mm, nn, nm i mn", "text": "Els grups nasals es pronuncien de manera diferent segons la paraula. En ***mm*** sonen les dos *m*: *primmirat* pri[mm]irat, *immers*, *commoure*. En ***nn*** la primera *n* és muda: *annals* a[n]als, *bienni* bie[n]i, *innocent*, *connectar*. En ***nm*** la *n* s'assimila i es pronuncia [mm]: *tanmateix* ta[mm]ateix, *enmig* e[mm]ig. En ***mn*** interior sonen les dos consonants (*amnèsia* a[mn]èsia), però a començament de paraula la *m* és muda: *mnemotècnia* [n]emotècnia, com *gnom* [nóm].", "table": {"head": ["grup", "exemple", "pronúncia"], "rows": [["*mm*", "*primmirat*", "pri[mm]irat"], ["*nn*", "*annals*, *bienni*", "a[n]als, bie[n]i"], ["*nm*", "*tanmateix*, *enmig*", "ta[mm]ateix, e[mm]ig"], ["*mn* interior", "*amnèsia*", "a[mn]èsia"], ["*mn-* inicial", "*mnemotècnia*", "[n]emotècnia"]]}, "watch": [{"wrong": "*anals* (‘publicació’), *bieni*", "right": "annals, bienni"}, {"wrong": "*tammateix*, *emmig*", "right": "tanmateix, enmig"}]}], "remember": ["*-l* final: *bonítol*, *cerebel*, *cérvol* (o *cervo*), *nínxol*.", "*Tl* geminada preferent: *batle* [bálle], *butla* [búlla]; *vila* / *vil·la*.", "*N* davant de *f* en *con-*, *in-*, *en-* (*enfadar*), però *àmfora*; *tramvia*, *triumvir*; *Enric*, *somriure*.", "*Tron*, *orangutan*; *betum*.", "*Pri[mm]irat*, *a[n]als*, *ta[mm]ateix*, *e[mm]ig*, *a[mn]èsia*, *[n]emotècnia*."], "sources": [{"gram": "GNV", "section": "4.12", "title": "Les grafies m, n, mp, tm i tn", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_12"}, {"gram": "GVB", "section": "6.19", "title": "Les grafies m, n i mp", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_19"}, {"gram": "GVB", "section": "6.20", "title": "Les grafies tm i tn", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_20"}, {"gram": "GNV", "section": "4.14", "title": "Les grafies l, l·l i tl", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_14"}, {"gram": "GVB", "section": "6.17", "title": "Les grafies l, l·l i tl", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_17"}, {"gram": "GNV", "section": "4.15", "title": "Les grafies ll i tll", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_15"}, {"gram": "GNV", "section": "1.3.2.5", "title": "Les consonants laterals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_5"}, {"gram": "GVB", "section": "2.5.1", "title": "Pronunciacions recomanables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_5_1"}, {"gram": "GNV", "section": "1.3.2.7", "title": "Les consonants nasals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_7"}, {"gram": "GVB", "section": "2.7.1", "title": "Pronunciacions recomanables", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=2_7_1"}, {"gram": "GNV", "section": "5.1.2", "title": "Observacions sobre l'accentuació de les ee", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=5_1_2"}, {"gram": "GNV", "section": "3.1.2", "title": "Normes de separació sil·làbica", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=3_1_2"}]}},
  {"type": "c2_fon_rotiques_h", "lesson": {"intro": "Aprendràs a decidir entre *r* i *rr* en compostos i derivats amb prefix, a escriure ròtiques difícils i a usar la *h* en préstecs, cultismes i noms propis: quan és muda, quan és aspirada, com es representen altres sons i quines parelles distingix.", "blocks": [{"title": "r o rr en compostos i derivats", "text": "El so vibrant [r] s'escriu ***rr*** entre vocals: *arrítmia*, *correferent*, *prerrogativa*, *trirrem*, *erradicar*, *ornitorrinc*, *otorrinolaringòleg*. Però s'escriu ***r*** simple quan seguix un **prefix**, una forma prefixada o un formant de compost acabat en vocal que es percep com a tal: *autoretrat*, *contrarestar*, *vicerector*, *grecoromà* greco[r]omà, *iberoromànic*, *semirecta*, i en els compostos amb guionet: *mata-rates*, *malva-rosa*, *Vila-real*. Com que hi ha derivats cultes de cada tipus, en cas de dubte cal consultar el diccionari.", "table": {"head": ["rr", "r darrere de prefix o formant"], "rows": [["*arrítmia*, *correferent*", "*autoretrat*, *vicerector*"], ["*prerrogativa*, *trirrem*", "*contrarestar*, *semirecta*"], ["*ornitorrinc*, *otorrino-*", "*grecoromà*, *iberoromànic*"], ["*erradicar*", "*mata-rates*, *Vila-real*"]]}, "watch": [{"wrong": "*arítmia*, *prerogativa*", "right": "arrítmia, prerrogativa"}, {"wrong": "*autorretrat*, *grecorromà*", "right": "autoretrat, grecoromà"}]}, {"title": "Ròtiques en paraules difícils", "text": "Algunes paraules d'ús formal tenen una ròtica que no coincidix amb altres llengües: l'arma és el ***sabre*** (*sable* en valencià és el color negre en heràldica); s'escriu ***crebantar*** (‘fer perdre consistència’); *erradicar*, *ornitorrinc* i el formant *otorrino-* porten *rr*.", "examples": ["L'oficial duia un **sabre** a la cintura.", "Cal **erradicar** les causes del problema.", "L'**ornitorrinc** és un mamífer que pon ous.", "Demà tinc hora amb l'**otorrinolaringòleg**."], "watch": [{"wrong": "*sable* (arma)", "right": "sabre"}, {"wrong": "*quebrantar*, *eradicar*", "right": "crebantar, erradicar"}, {"wrong": "*ornitorinc*, *otorinolaringòleg*", "right": "ornitorrinc, otorrinolaringòleg"}]}, {"title": "La h en préstecs i cultismes", "text": "La *h* normalment és **muda** i s'escriu per etimologia. En els préstecs adaptats pot ser aspirada o muda: *hàmster* [hámsteɾ], però *handbol* [ambɔ́l]. Molts cultismes poc usuals duen *h* inicial dels formants grecs (*hidro-*, *hexa-*, *holo-*, *hemo-*, *heli-*): *hidròfob*, *hídric*, *hexagonal* [egzaɣonál], *holograma*, *hemorràgia*, *hèlix*, *híbrid*; i alguns tenen *h* intercalada: *subtrahend* [suptɾaént].", "examples": ["És un material **hidròfob**: repel·lix l'aigua.", "El museu exposa un **holograma** de la peça original.", "En la resta, el **subtrahend** es resta del minuend."]}, {"title": "La h aspirada i altres representacions", "text": "La *h* es pronuncia **aspirada** [h] en algunes interjeccions (*ehem!*, *ha, ha, ha!*, *he, he!*, *ha!*), en antropònims no adaptats i els seus derivats (*Hegel*, *hegelià*), en préstecs no adaptats (*hippy*, *hip-hop*, *apartheid*) i en topònims adaptats (*el Sàhara*) i no adaptats (*Hawaii*, *Hollywood*, *Honolulu*). Per això davant d'estes paraules no s'apostrofa: *de Hollywood*, *el hegelianisme*. El dígraf ***kh*** i la ***h*** darrere de consonant representen en alguns noms un so fricatiu velar: *Khartum*, *sikh* [síx].", "watch": [{"wrong": "*d'Hollywood*, *l'hegelianisme*", "right": "de Hollywood, el hegelianisme"}, {"wrong": "*[a]mster*, *[h]andbol*", "right": "[h]àmster, [a]mbol"}]}, {"title": "h diferent d'altres llengües i parelles", "text": "Algunes paraules no tenen *h* en valencià i sí en castellà (*coet*, *orxata*, *truà*), i altres al revés (*harmonia*, *subhasta*). A més, la *h* distingix parelles de paraules de significat diferent que es pronuncien igual o de manera semblant.", "table": {"head": ["sense h", "amb h"], "rows": [["*ala* (d'un ocell, d'un edifici)", "*hala!* (interjecció)"], ["*aprendre* (adquirir coneixements)", "*aprehendre* (copsar mentalment)"], ["*om* (arbre)", "*hom* (pronom impersonal)"], ["*ostatge* (persona retinguda com a garantia)", "*hostatge* (acció d'hostatjar, allotjament)"]]}, "watch": [{"wrong": "*cohet*, *horxata*, *truhà*", "right": "coet, orxata, truà"}, {"wrong": "*armonia*, *subasta*", "right": "harmonia, subhasta"}]}], "remember": ["*Rr* entre vocals (*arrítmia*, *correferent*, *prerrogativa*, *trirrem*), però *r* darrere de formant (*autoretrat*, *grecoromà*, *mata-rates*, *Vila-real*).", "*Sabre*, *crebantar*, *erradicar*, *ornitorrinc*, *otorrino-*.", "*H* aspirada: *ehem!*, *hegelià*, *hippy*, *el Sàhara*, *Hawaii*: sense apòstrof.", "*Hàmster* [h], *handbol* [ambɔ́l]; cultismes amb *h*: *hidròfob*, *hexagonal*, *hèlix*, *subtrahend*.", "*Coet*, *orxata*, *truà*; *harmonia*, *subhasta*; *ala/hala*, *om/hom*, *ostatge/hostatge*."], "sources": [{"gram": "GNV", "section": "4.16", "title": "Les grafies r i rr", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_16"}, {"gram": "GVB", "section": "6.22", "title": "Les grafies r i rr", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_22"}, {"gram": "GNV", "section": "1.3.2.6", "title": "Les consonants ròtiques", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=1_3_2_6"}, {"gram": "GNV", "section": "4.17", "title": "La grafia h", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=4_17"}, {"gram": "GVB", "section": "6.23", "title": "La grafia h", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=6_23"}, {"gram": "GVB", "section": "10.6", "title": "L'apostrofació davant de h aspirada", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=10_6"}, {"gram": "GNV", "section": "5.4", "title": "L'apòstrof", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=5_4"}, {"gram": "GNV", "section": "35.1", "title": "Conceptes generals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=35_1"}, {"gram": "GNV", "section": "5.3", "title": "El guionet", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=5_3"}, {"gram": "GVB", "section": "9.1", "title": "Usos del guionet", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=9_1"}]}},
  {"type": "c2_fon_convencions", "lesson": {"intro": "Aprendràs a usar les majúscules en els casos d'ús formal (càrrecs, tractaments, institucions, topònims i vies urbanes), els tipus de lletra, les abreviatures, els símbols, les sigles i els acrònims, i a decidir si una quantitat va en lletra o en xifres, amb mesura, coherència i pertinència.", "blocks": [{"title": "Funció demarcativa i funció distintiva", "text": "La majúscula té **funció demarcativa** quan marca l'inici d'un text o d'una frase: a principi de paràgraf, després de punt i després de *?*, *!* o *...* que tanquen la frase; si no la tanquen, es continua en minúscula (*La seua situació és, ai!, molt precària*). Té **funció distintiva** quan identifica un nom propi. La majúscula **no altera l'accent ni la dièresi** (*Àngel*, *ALTA TRAÏCIÓ*); en els dígrafs només va en majúscula la primera lletra (*Txad*, *Lluïsa*) i en els compostos, la del primer constituent (*Sud-àfrica*, *Vila-real*).", "watch": [{"wrong": "*TXad*, *LLuïsa*", "right": "Txad, Lluïsa"}, {"wrong": "*Sud-Àfrica*, *Vila-Real*", "right": "Sud-àfrica, Vila-real"}]}, {"title": "Càrrecs, tractaments i formes protocol·làries", "text": "Els **càrrecs** i títols s'escriuen en minúscula, vagen o no davant del nom: *la presidenta de les Corts*, *el conseller d'Indústria*, *el degà de la Facultat de Filologia*. Les **formes de tractament** que precedixen un nom també van en minúscula (*sor Isabel*, *mossén Alcover*, *la senyora Jacinta*), però les seues abreviatures sempre en majúscula (*Sr.*, *Sra.*, *Mn.*). Les **formes protocol·làries** van amb majúscula inicial.", "table": {"head": ["cas", "exemple"], "rows": [["càrrec", "*l'alcaldessa d'Elx*, *el rector de la Universitat*"], ["tractament + nom", "*mossén Alcover*, *el Sr. Romeu*"], ["*sant* integrat en un nom", "*Santa Pola*, *el dia de Santa Cecília*"], ["forma protocol·lària", "*el Molt Honorable Senyor President de la Generalitat*"], ["tractament en una via urbana", "*la plaça del Pintor Jacomart*"]]}}, {"title": "Institucions, entitats, topònims i vies urbanes", "text": "Els noms d'**institucions** i **entitats** porten majúscula en substantius i adjectius (*la Conselleria d'Agricultura, Pesca i Alimentació*, *l'Ajuntament de Gandia*), també en la menció abreujada (*la Conselleria*, *l'Acadèmia*); van en minúscula en plural o amb sentit genèric (*les conselleries implicades*) i en les denominacions correferents (*el consistori*, *l'executiu*). En les institucions públiques i religioses, majúscula en el substantiu i minúscula en l'adjectiu: *l'Estat espanyol*, *l'Administració pública*. En els **topònims** valencians, l'article va en minúscula (*l'Eliana*, *la Font d'en Carròs*), però no en els no adaptats (*El Escorial*, *Le Havre*). Els genèrics de vies i accidents van en minúscula (*el carrer Ample*, *la plaça de l'Arc*, *la serra de Mariola*), excepte si formen part del nom (*la Vall d'Albaida*).", "watch": [{"wrong": "*la Plaça de l'Arc*, *la Serra de Mariola*", "right": "la plaça de l'Arc, la serra de Mariola"}, {"wrong": "*L'Eliana* (dins de frase), *el Consistori*", "right": "l'Eliana, el consistori"}]}, {"title": "Redona, cursiva, negreta i versaleta", "text": "La **redona** és la lletra base; hi van també les marques, els establiments i els préstecs adaptats. La **cursiva** marca títols d'obres i publicacions, noms de naus, usos metalingüístics, pseudònims que acompanyen el nom, formes incorrectes conscients i préstecs no adaptats; si el text ja està en cursiva, estes funcions passen a la redona. La **negreta** destaca títols, entrades de diccionari i noms propis en notícies. La **versaleta** s'usa per a xifres romanes que acompanyen una paraula en minúscula (segle xviii, però Pius V), ètims, cognoms en bibliografies i personatges de teatre.", "table": {"head": ["tipus", "usos característics"], "rows": [["redona", "*míting*, *escàner*; marques i establiments"], ["cursiva", "títols, préstecs no adaptats, usos metalingüístics: *Els horts*, *country*, el verb *caldre*"], ["negreta", "títols d'apartats, lemes de diccionari"], ["versaleta", "xifres romanes amb paraula en minúscula (segle xviii, volum iii), ètims, cognoms en bibliografies"]]}}, {"title": "Abreviatures, símbols, sigles i acrònims", "text": "Les **abreviatures** acaben en punt o barra (*pàg.*, *c/*), mantenen l'accent (*núm.*), van en minúscula excepte els tractaments (*Sra.*), poden fer femení i plural (*Il·lma.*, *pp.*), es lligen desplegades i no es separen de la xifra a final de línia; el seu punt es fon amb el punt final. Els **símbols** no porten punt, són **invariables** (*5 km*) i la majúscula hi és fixa (*W*, *Na*, *N*). Les **sigles** van en majúscula, sense punts ni accents, amb el gènere de la primera paraula (*la CIA*, *els EUA*); en les lexicalitzades s'admet el plural amb *-s* (*les ONGs*), i algunes s'escriuen ja en minúscula (*sida*, *ovni*). Els **acrònims** admeten també la inicial sola en majúscula (*Ivaj*).", "watch": [{"wrong": "*5 kms.*, *10 Km*", "right": "5 km, 10 km"}, {"wrong": "*pag.*, *num.*", "right": "pàg., núm."}, {"wrong": "*les O.N.G.*", "right": "les ONG (o les ONGs)"}]}, {"title": "Xifres o lletres, i criteris d'ús", "text": "Dins del text, els cardinals se solen escriure amb **lletra del zero al nou** i amb **xifres a partir del 10**: *La pàgina dos i la 34 estan ratllades*. En les xifres, el punt separa els milers (*72.000 euros*) i la coma els decimals (*6,5 metres*); les hores admeten punt o dos punts (*8.30*, *8:30*), i els ordinals s'abreugen amb l'última lletra (*1r*, *4a*, *4ts*). Davant de xifres que comencen per vocal s'apostrofa: *l'11 de gener*. Per damunt de tot, cal **mesura** (no abusar de majúscules, cursives ni abreviacions), **coherència** (el mateix criteri en tot el text) i **pertinència** (abreviar només quan el lector ho pot entendre sense esforç).", "examples": ["Només caben **nou** taules en l'aula **205**.", "L'import total de les millores és de **72.000** euros.", "El vol arriba a les **8.30** hores i ix de la **4a** porta."]}], "remember": ["Majúscula demarcativa (inici de frase) i distintiva (nom propi), sense perdre accent ni dièresi: *Txad*, *Sud-àfrica*.", "Càrrecs i tractaments en minúscula (*el conseller*, *mossén Alcover*); protocol·làries amb majúscula (*el Molt Honorable Senyor President*).", "*La Conselleria d'Educació*, però *les conselleries*; *l'Eliana*, *el carrer Ample*, *la Vall d'Albaida*.", "Cursiva per a títols, préstecs no adaptats i usos metalingüístics; versaleta per a les xifres romanes (segle xviii).", "Símbols sense punt ni plural (*5 km*); sigles sense punts (*ONG*); abreviatures amb accent (*pàg.*).", "Del zero al nou en lletra; a partir del 10 en xifres; mesura, coherència i pertinència."], "sources": [{"gram": "GNV", "section": "6.1.1", "title": "Consideracions generals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=6_1_1"}, {"gram": "GNV", "section": "6.1.2", "title": "La funció demarcativa", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=6_1_2"}, {"gram": "GNV", "section": "6.1.3", "title": "La funció distintiva", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=6_1_3"}, {"gram": "GVB", "section": "12.10", "title": "Càrrecs i títols nobiliaris", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=12_10"}, {"gram": "GVB", "section": "12.11", "title": "Formes de tractament", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=12_11"}, {"gram": "GVB", "section": "12.12", "title": "Formes protocol·làries de tractament", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=12_12"}, {"gram": "GVB", "section": "12.16", "title": "Noms d'institucions, organismes i empreses", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=12_16"}, {"gram": "GVB", "section": "12.19", "title": "Noms d'institucions públiques i religioses", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=12_19"}, {"gram": "GVB", "section": "12.25", "title": "Noms de lloc", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=12_25"}, {"gram": "GNV", "section": "6.2", "title": "Els tipus de lletra", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=6_2"}, {"gram": "GNV", "section": "6.3.1", "title": "Les abreviatures", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=6_3_1"}, {"gram": "GNV", "section": "6.3.2", "title": "Els símbols", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=6_3_2"}, {"gram": "GNV", "section": "6.3.3", "title": "Les sigles", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=6_3_3"}, {"gram": "GNV", "section": "18.3.2", "title": "La forma dels numerals cardinals", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=18_3_2"}, {"gram": "GNV", "section": "7.3.3", "title": "El punt", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=7_3_3"}]}},
  {"type": "c2_fon_puntuacio", "lesson": {"intro": "Aprendràs a puntuar les oracions compostes, a decidir quan un element explicatiu va entre comes i quan un especificatiu no en du, a usar el punt i coma, a graduar els incisos amb comes, guions i parèntesis i a evitar les comes que separen el subjecte del verb o el verb dels seus complements.", "blocks": [{"title": "Les oracions compostes", "text": "En la **coordinació**, no es posa coma davant de *i*, *o*, *ni* que tanquen una sèrie, però sí quan la conjunció introduïx un contingut diferent (una conclusió, un matís d'adversitat) o unix membres independents: *Actuà sense contemplacions, i probablement eixe va ser el seu error*. Les **adversatives** van precedides de coma (*no ha sigut ell, sinó el seu germà*). Les **subordinades** temporals, condicionals i concessives **anteposades** se separen amb coma (*Quan arribàrem al teatre, la representació ja havia començat*); si són curtes, es pot ometre, i si van posposades, no cal. També van entre comes els connectors (*no obstant això*, *per tant*) i les clàusules absolutes, i la coma marca l'elisió del verb.", "examples": ["*Si no t'agrada estudiar, és millor que et poses a treballar.*", "*Ja havien començat a dinar quan arribàrem.* (posposada: sense coma)", "*Conclòs el tràmit d'audiència, l'instructor ha de trametre l'expedient.*", "*Una cosa és voler, i una altra, poder.* (elisió del verb)"]}, {"title": "Elements explicatius i especificatius", "text": "Les **relatives explicatives** i les **aposicions** que afigen una informació accessòria van entre comes; les **especificatives**, que restringixen el significat del nom, no en porten. La coma canvia el sentit: *Els espectadors, que havien aguantat fins al final, xiularen* (tots) / *Els espectadors que havien aguantat fins al final xiularen* (només eixos).", "table": {"head": ["explicatiu (amb comes)", "especificatiu (sense comes)"], "rows": [["*El peix, que és molt bo per a la salut, ha de consumir-se fresc.*", "*El peix que van pescar ahir ja s'ha venut.*"], ["*Benaguasil, situat en el Camp de Túria, té prop de 10.000 habitants.*", "*El poble situat al costat del riu s'inunda sovint.*"]]}}, {"title": "El punt i coma", "text": "El **punt i coma** marca una pausa més gran que la coma i més xicoteta que el punt. S'usa per a separar els membres d'una **enumeració complexa** que ja contenen comes (l'últim, introduït per *i*, va precedit de coma); davant de connectors adversatius, concessius o consecutius (*no obstant això*, *amb tot*, *per consegüent*) quan unixen estructures llargues o amb comes internes, i entre frases completes estretament unides pel significat.", "examples": ["*Hi assistiren la directora general, Sra. Melià; el secretari de la Comissió, Sr. Martí, i el primer vocal, Sr. Grau.*", "*L'informe és negatiu; no obstant això, si s'esmenen les deficiències, es revisarà l'expedient.*", "*Hui encara estem a temps d'actuar; demà, probablement, ja serà massa tard.*"]}, {"title": "Incisos: comes, guions i parèntesis", "text": "Un incís es pot marcar amb **comes**, **guions** o **parèntesis**, en una gradació de menys a més separació respecte a l'oració: les comes l'integren en el discurs; els guions el destaquen més, i els parèntesis l'aïllen com una informació complementària (aclariments, dades, referències). El guió de tancament es pot ometre davant de punt. Si el parèntesi coincidix amb una coma, un punt i coma o dos punts, estos van **darrere**; el punt va dins només si el parèntesi comença la frase. Per a un parèntesi dins d'un altre s'usen **claudàtors**.", "examples": ["*El pressupost, com era previsible, no arriba per a tot.*", "*La falta de primeres matèries —un dels principals problemes de l'economia— ha frenat la indústria.*", "*La vila s'emplaça en l'entrada de la serra d'Espadà (1.030 metres), pròxima al riu Anna.*"]}, {"title": "On no va la coma", "text": "No s'ha d'escriure coma entre el **subjecte** i el **verb**, encara que el subjecte siga llarg, ni entre el verb i els seus **complements** posposats (directe, indirecte, atribut o predicatiu), ni entre estos complements. L'única excepció és un incís, que va **entre dos comes**; i si el subjecte és una enumeració tancada amb *etc.*, es posa coma després d'*etc.*", "watch": [{"wrong": "*Els representants de les organitzacions sindicals, van manifestar la seua oposició.*", "right": "Els representants de les organitzacions sindicals van manifestar la seua oposició."}, {"wrong": "*El president de la patronal va manifestar, que no acudiria a la reunió.*", "right": "El president de la patronal va manifestar que no acudiria a la reunió."}, {"wrong": "*Volem agrair a tots els ciutadans, la confiança depositada.*", "right": "Volem agrair a tots els ciutadans la confiança depositada."}, {"wrong": "*La causa principal del retard en les obres de l'estació, és la falta de pressupost.*", "right": "La causa principal del retard en les obres de l'estació és la falta de pressupost."}]}], "remember": ["Coma davant de *i* només si introduïx un contingut diferent o unix membres independents.", "Subordinada anteposada, amb coma (omissible si és curta); posposada, normalment sense.", "Explicatives i aposicions entre comes; especificatives sense comes.", "Punt i coma en enumeracions complexes i davant de connectors en estructures llargues.", "Incisos: comes < guions < parèntesis; els signes de pausa van darrere del parèntesi.", "Mai coma entre subjecte i verb, ni entre el verb i el CD, el CI, l'atribut o el predicatiu."], "sources": [{"gram": "GNV", "section": "7.3.1", "title": "La coma", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=7_3_1"}, {"gram": "GVB", "section": "15.3.1", "title": "Usos de la coma", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_3_1"}, {"gram": "GVB", "section": "15.3.3", "title": "Usos incorrectes de la coma", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_3_3"}, {"gram": "GNV", "section": "7.3.2", "title": "El punt i coma", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=7_3_2"}, {"gram": "GVB", "section": "15.4", "title": "El punt i coma", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_4"}, {"gram": "GNV", "section": "7.5.1", "title": "Els guions", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=7_5_1"}, {"gram": "GVB", "section": "15.10", "title": "Els guions", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_10"}, {"gram": "GNV", "section": "7.5.2", "title": "Els parèntesis", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=7_5_2"}, {"gram": "GVB", "section": "15.11.2", "title": "Combinació dels parèntesis amb altres signes de puntuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GVB&index=15_11_2"}, {"gram": "GNV", "section": "7.5.3", "title": "Els claudàtors", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=7_5_3"}, {"gram": "GNV", "section": "7.2", "title": "Contacte entre signes de puntuació", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=7_2"}, {"gram": "GNV", "section": "8.5.3", "title": "Les oracions simples i les compostes", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=8_5_3"}, {"gram": "GNV", "section": "8.5.1", "title": "El predicat i els complements", "url": "https://www.avl.gva.es/gnv/buscador.jsp?gramatica=GNV&index=8_5_1"}]}}
]$data$::jsonb) AS l(type text, lesson jsonb)
WHERE r.category = 'fonetica_ortografia' AND r.difficulty = 'C2' AND r.type = l.type;
